import{_ as a,H as o,f as e,i as r}from"./chunks/framework.Cvt1eIE0.js";const u=JSON.parse('{"title":"PCIe Flow Control 知识点总结","description":"","frontmatter":{},"headers":[],"relativePath":"pcie/pcie-flow-control.md","filePath":"pcie/pcie-flow-control.md"}'),n={name:"pcie/pcie-flow-control.md"};function l(i,t,d,s,h,p){return o(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="pcie-flow-control-知识点总结" tabindex="-1">PCIe Flow Control 知识点总结 <a class="header-anchor" href="#pcie-flow-control-知识点总结" aria-label="Permalink to &quot;PCIe Flow Control 知识点总结&quot;">​</a></h1><p><strong>来源：</strong> <a href="https://blog.chinaaet.com/justlxy/p/5100053464" target="_blank" rel="noreferrer">PCIe 扫盲——Flow Control 基础（一）</a><br><strong>整理时间：</strong> 2026-03-17<br><strong>相关 Spec：</strong> PCIe Base Spec 6.0/7.0 - Chapter 2 (Transaction Layer)</p><hr><h2 id="📊-目录" tabindex="-1">📊 目录 <a class="header-anchor" href="#📊-目录" aria-label="Permalink to &quot;📊 目录&quot;">​</a></h2><ol><li><a href="#1-flow-control-的目的">Flow Control 的目的</a></li><li><a href="#2-flow-control-的实现方式">Flow Control 的实现方式</a></li><li><a href="#3-vc-virtual-channel-与-flow-control">VC（Virtual Channel）与 Flow Control</a></li><li><a href="#4-6-种-flow-control-buffer-类型">6 种 Flow Control Buffer 类型</a></li><li><a href="#5-flow-control-credits单位">Flow Control Credits（单位）</a></li><li><a href="#6-point-to-point-vs-end-to-end">Point-to-Point vs End-to-End</a></li><li><a href="#7-完整数据流示例">完整数据流示例</a></li><li><a href="#8-与-pcie-70-项目的关联">与 PCIe 7.0 项目的关联</a></li></ol><hr><h2 id="_1️⃣-flow-control-的目的" tabindex="-1">1️⃣ Flow Control 的目的 <a class="header-anchor" href="#_1️⃣-flow-control-的目的" aria-label="Permalink to &quot;1️⃣ Flow Control 的目的&quot;">​</a></h2><p><strong>核心作用：</strong> 保证发送端永远不会发送接收端不能接收的 TLP（事务层包）</p><h3 id="pcie-vs-pci-对比" tabindex="-1">PCIe vs PCI 对比 <a class="header-anchor" href="#pcie-vs-pci-对比" aria-label="Permalink to &quot;PCIe vs PCI 对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>PCIe</th><th>PCI（对比）</th></tr></thead><tbody><tr><td><strong>发送前检查</strong></td><td>✅ 检查接收端 Buffer 空间</td><td>❌ 先尝试发送</td></tr><tr><td><strong>接收端状态</strong></td><td>✅ 知道接收端能否接收</td><td>❌ 不知道接收端是否就绪</td></tr><tr><td><strong>等待周期</strong></td><td>❌ 不会插入等待</td><td>✅ 可能插入多个等待周期</td></tr><tr><td><strong>重发机制</strong></td><td>❌ 不需要重发</td><td>✅ 可能需要重发（Retries）</td></tr></tbody></table><p><strong>设计意义：</strong></p><ul><li>提高总线传输效率</li><li>减少延迟和功耗</li><li>支持多 VC（Virtual Channel）并发通信</li></ul><hr><h2 id="_2️⃣-flow-control-的实现方式" tabindex="-1">2️⃣ Flow Control 的实现方式 <a class="header-anchor" href="#_2️⃣-flow-control-的实现方式" aria-label="Permalink to &quot;2️⃣ Flow Control 的实现方式&quot;">​</a></h2><h3 id="机制概述" tabindex="-1">机制概述 <a class="header-anchor" href="#机制概述" aria-label="Permalink to &quot;机制概述&quot;">​</a></h3><p><strong>实现方式：</strong> 通过数据链路层之间的 <strong>DLLP（Data Link Layer Packet）</strong> 实现</p><p><strong>关键特性：</strong></p><ul><li><strong>点到点（Point-to-Point）</strong> - 只在相邻端口之间传输</li><li><strong>不是端到端（End-to-End）</strong> - 不会跨越中间设备</li><li><strong>Buffer 和计数器在事务层</strong> - 事务层参与 Flow Control 管理</li></ul><h3 id="初始化流程" tabindex="-1">初始化流程 <a class="header-anchor" href="#初始化流程" aria-label="Permalink to &quot;初始化流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Receiver ─────DLLP─────► Transmitter</span></span>
<span class="line"><span>报告 Buffer 大小          接收并记录</span></span>
<span class="line"><span></span></span>
<span class="line"><span>周期性发送 FC 状态         更新 FC Counter</span></span></code></pre></div><hr><h2 id="_3️⃣-vc-virtual-channel-与-flow-control" tabindex="-1">3️⃣ VC（Virtual Channel）与 Flow Control <a class="header-anchor" href="#_3️⃣-vc-virtual-channel-与-flow-control" aria-label="Permalink to &quot;3️⃣ VC（Virtual Channel）与 Flow Control&quot;">​</a></h2><h3 id="spec-规定" tabindex="-1">Spec 规定 <a class="header-anchor" href="#spec-规定" aria-label="Permalink to &quot;Spec 规定&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>规定值</th><th>说明</th></tr></thead><tbody><tr><td><strong>最大 VC 数</strong></td><td>8 个</td><td>每个端口最多支持 8 个 VC</td></tr><tr><td><strong>Buffer 独立性</strong></td><td>完全独立</td><td>每个 VC 的 Flow Control Buffer 独立管理</td></tr><tr><td><strong>相互影响</strong></td><td>无</td><td>某一 VC 的 Buffer 满不影响其他 VC</td></tr></tbody></table><h3 id="端口类型" tabindex="-1">端口类型 <a class="header-anchor" href="#端口类型" aria-label="Permalink to &quot;端口类型&quot;">​</a></h3><ul><li><strong>Endpoint:</strong> 一般只有 1 个端口</li><li><strong>Root Complex:</strong> 1 个或多个端口</li><li><strong>Switch:</strong> 1 个 Upstream 端口 + 多个 Downstream 端口</li></ul><hr><h2 id="_4️⃣-6-种-flow-control-buffer-类型" tabindex="-1">4️⃣ 6 种 Flow Control Buffer 类型 <a class="header-anchor" href="#_4️⃣-6-种-flow-control-buffer-类型" aria-label="Permalink to &quot;4️⃣ 6 种 Flow Control Buffer 类型&quot;">​</a></h2><h3 id="分类依据" tabindex="-1">分类依据 <a class="header-anchor" href="#分类依据" aria-label="Permalink to &quot;分类依据&quot;">​</a></h3><p><strong>TLP 三大类：</strong></p><ol><li>Posted Transactions - Memory Writes, Messages</li><li>Non-Posted Transactions - Memory Reads, Configuration, IO</li><li>Completions - Read/Write Completion</li></ol><p><strong>Header/Data 分离：</strong> Header Buffer + Data Buffer</p><p><strong>组合：3 × 2 = 6 种 Buffer</strong></p><h3 id="buffer-类型" tabindex="-1">Buffer 类型 <a class="header-anchor" href="#buffer-类型" aria-label="Permalink to &quot;Buffer 类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>缩写</th><th>用途</th></tr></thead><tbody><tr><td>Posted Request Header</td><td>PH</td><td>Memory Write/Message Header</td></tr><tr><td>Posted Request Data</td><td>PD</td><td>Write Data</td></tr><tr><td>Non-Posted Request Header</td><td>NPH</td><td>Read/Config/IO Header</td></tr><tr><td>Non-Posted Request Data</td><td>NPD</td><td>(通常为空)</td></tr><tr><td>Completion Header</td><td>CPLH</td><td>Read/Write Completion Header</td></tr><tr><td>Completion Data</td><td>CPLD</td><td>Read Data</td></tr></tbody></table><hr><h2 id="_5️⃣-flow-control-credits-单位" tabindex="-1">5️⃣ Flow Control Credits（单位） <a class="header-anchor" href="#_5️⃣-flow-control-credits-单位" aria-label="Permalink to &quot;5️⃣ Flow Control Credits（单位）&quot;">​</a></h2><h3 id="存储单元定义" tabindex="-1">存储单元定义 <a class="header-anchor" href="#存储单元定义" aria-label="Permalink to &quot;存储单元定义&quot;">​</a></h3><p><strong>Flow Control Credit</strong> 是 Buffer 的基本计量单位</p><table tabindex="0"><thead><tr><th>Buffer 类型</th><th>Unit 大小</th><th>说明</th></tr></thead><tbody><tr><td>Request Header</td><td>5 DW</td><td>每个 TLP Header 占 1 个 unit</td></tr><tr><td>Completion Header</td><td>4 DW</td><td>每个 CPL Header 占 1 个 unit</td></tr><tr><td>Data</td><td>4 DW (16 字节)</td><td>Data Buffer 按 16 字节对齐</td></tr></tbody></table><p><strong>注：</strong> DW = Double Word = 4 字节 = 32-bit</p><h3 id="buffer-大小限制" tabindex="-1">Buffer 大小限制 <a class="header-anchor" href="#buffer-大小限制" aria-label="Permalink to &quot;Buffer 大小限制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Buffer 类型</th><th>最小值</th><th>说明</th></tr></thead><tbody><tr><td>PH</td><td>1 unit</td><td>至少能存 1 个 Header</td></tr><tr><td>PD</td><td>0 unit</td><td>0 表示无限（Infinite）</td></tr><tr><td>NPH</td><td>1 unit</td><td>至少能存 1 个 Header</td></tr><tr><td>NPD</td><td>0 unit</td><td>通常为空</td></tr><tr><td>CPLH</td><td>1 unit</td><td>至少能存 1 个 Header</td></tr><tr><td>CPLD</td><td>0 unit</td><td>可选</td></tr></tbody></table><hr><h2 id="_6️⃣-point-to-point-vs-end-to-end" tabindex="-1">6️⃣ Point-to-Point vs End-to-End <a class="header-anchor" href="#_6️⃣-point-to-point-vs-end-to-end" aria-label="Permalink to &quot;6️⃣ Point-to-Point vs End-to-End&quot;">​</a></h2><h3 id="拓扑示例" tabindex="-1">拓扑示例 <a class="header-anchor" href="#拓扑示例" aria-label="Permalink to &quot;拓扑示例&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Endpoint ◄────► Switch ◄────► Root Port</span></span>
<span class="line"><span>  Port 0      Port 0/2       Port 0</span></span>
<span class="line"><span>   Link 1       Link 2</span></span></code></pre></div><h3 id="point-to-point-flow-control" tabindex="-1">Point-to-Point（Flow Control） <a class="header-anchor" href="#point-to-point-flow-control" aria-label="Permalink to &quot;Point-to-Point（Flow Control）&quot;">​</a></h3><p><strong>定义：</strong> Flow Control 只在<strong>物理相邻</strong>的两个端口之间进行</p><ul><li>✅ Link 1: Endpoint Port 0 ↔ Switch Port 0</li><li>✅ Link 2: Switch Port 2 ↔ Root Port 0</li><li>❌ 不是：Endpoint ↔ Root（不相邻）</li></ul><p><strong>优势：</strong></p><ul><li>延迟低（只等相邻设备）</li><li>效率高（链路充分利用）</li><li>每个链路独立管理</li></ul><h3 id="end-to-end-completion" tabindex="-1">End-to-End（Completion） <a class="header-anchor" href="#end-to-end-completion" aria-label="Permalink to &quot;End-to-End（Completion）&quot;">​</a></h3><p><strong>定义：</strong> 从源头直接到目的地，跨越中间所有设备</p><p><strong>例子：</strong> Memory Read 的 Completion 从 Completer 直接返回 Requester</p><h3 id="对比" tabindex="-1">对比 <a class="header-anchor" href="#对比" aria-label="Permalink to &quot;对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>Point-to-Point</th><th>End-to-End</th></tr></thead><tbody><tr><td><strong>范围</strong></td><td>相邻端口之间</td><td>源头到目的地</td></tr><tr><td><strong>跨越设备</strong></td><td>❌ 不能</td><td>✅ 可以</td></tr><tr><td><strong>PCIe 例子</strong></td><td>Flow Control DLLP</td><td>Completion TLP</td></tr><tr><td><strong>层</strong></td><td>数据链路层</td><td>事务层</td></tr></tbody></table><hr><h2 id="_7️⃣-完整数据流示例" tabindex="-1">7️⃣ 完整数据流示例 <a class="header-anchor" href="#_7️⃣-完整数据流示例" aria-label="Permalink to &quot;7️⃣ 完整数据流示例&quot;">​</a></h2><h3 id="memory-write-流程" tabindex="-1">Memory Write 流程 <a class="header-anchor" href="#memory-write-流程" aria-label="Permalink to &quot;Memory Write 流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Step 1: Endpoint 检查 Switch 的 Buffer</span></span>
<span class="line"><span>Endpoint ──FC Check──► Switch</span></span>
<span class="line"><span>         ◄──FC DLLP───</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Step 2: Switch 接收并存储到 Rx Buffer</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Step 3: Switch 检查 Root 的 Buffer</span></span>
<span class="line"><span>Switch ──FC Check──► Root</span></span>
<span class="line"><span>       ◄──FC DLLP───</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Step 4: Root 接收</span></span></code></pre></div><hr><h2 id="_8️⃣-与-pcie-7-0-项目的关联" tabindex="-1">8️⃣ 与 PCIe 7.0 项目的关联 <a class="header-anchor" href="#_8️⃣-与-pcie-7-0-项目的关联" aria-label="Permalink to &quot;8️⃣ 与 PCIe 7.0 项目的关联&quot;">​</a></h2><h3 id="设计注意事项" tabindex="-1">设计注意事项 <a class="header-anchor" href="#设计注意事项" aria-label="Permalink to &quot;设计注意事项&quot;">​</a></h3><ol><li><strong>必须实现 Flow Control 机制</strong> - Spec 强制要求</li><li><strong>6 个 Buffer 都需要管理</strong> - PH/PD/NPH/NPD/CPLH/CPLD</li><li><strong>FC DLLP 处理</strong> - 数据链路层支持</li><li><strong>计数器管理</strong> - 事务层维护 FC Counter</li><li><strong>多 VC 支持（可选）</strong> - 最多 8 个 VC</li></ol><h3 id="设计检查清单" tabindex="-1">设计检查清单 <a class="header-anchor" href="#设计检查清单" aria-label="Permalink to &quot;设计检查清单&quot;">​</a></h3><ul><li>[ ] 6 种 Buffer 类型已实现</li><li>[ ] FC Counter 逻辑正确</li><li>[ ] FC DLLP 生成/解析正常</li><li>[ ] 发送前 FC 检查逻辑</li><li>[ ] 多 VC 支持（如需要）</li><li>[ ] Buffer 大小符合 Spec 最小值</li><li>[ ] 初始化流程正确</li><li>[ ] 周期性 FC 更新机制</li></ul><hr><h2 id="📚-参考资料" tabindex="-1">📚 参考资料 <a class="header-anchor" href="#📚-参考资料" aria-label="Permalink to &quot;📚 参考资料&quot;">​</a></h2><ol><li>PCIe Base Specification 6.0/7.0 - Chapter 2: Transaction Layer</li><li><a href="https://blog.chinaaet.com/justlxy/p/5100053464" target="_blank" rel="noreferrer">PCIe 扫盲——Flow Control 基础（一）</a></li><li><a href="http://blog.chinaaet.com/justlxy/p/5100053481" target="_blank" rel="noreferrer">PCIe 扫盲目录篇</a></li></ol><hr><p><em>最后更新：2026-03-17</em><br><em>整理人：along</em></p>`,72)])])}const f=a(n,[["render",l]]);export{u as __pageData,f as default};
